(* ::Package:: *)

(* ======================================================================== *)
(* test20.m                                                      *)
(*                                                                          *)
(* Linear-trajectory bootstrap of the mixed A (massive, Z2 +) / B           *)
(* (massless, Z2 -) system, D = 10.  Bound on                               *)
(*                                                                          *)
(*      gABB^2 / ghatB   at fixed r = ghatA/ghatB  *)
(*                                                                          *)
(* for the isolated X2 (m2sq, J2).  Notation: mixed_state_bootstrap_v2.tex. *)
(*                                                                          *)
(*   v   = {ghatB, ghatA, gABB^2, nAB, nAAAA, nBBBB}                      *)
(*   a   = (a1, a2, -1, alpha, beta, gamma)          (upper bound)          *)
(*   a.v >= 0 (PSD) on every state,  maximize a.obj = -(a1 + a2 r)          *)
(*   SDPB objective V  =>  gABB^2/ghatB <= -V            *)
(*                                                                          *)
(* Usage:  wolframscript -file test20.m 1/5 1                    *)
(*         (mAsq, r; exact numbers.  Defaults 1/5 and 1.)                   *)
(* ======================================================================== *)

FileDir = If[
  StringQ[$InputFileName] && StringLength[$InputFileName] > 0,
  DirectoryName[ExpandFileName[$InputFileName]],
  Directory[]
];
Import[FileNameJoin[{FileDir, "..", "SDPB.m"}]];


(* ------------------------------------------------------------------------ *)
(* BLOCK 1.  Input                                                          *)
(* ------------------------------------------------------------------------ *)

mAsq = If[Length[$ScriptCommandLine] >= 2,
  ToExpression[StringTrim[$ScriptCommandLine[[2]]]], 1/5];
rRatio = If[Length[$ScriptCommandLine] >= 3,
  ToExpression[StringTrim[$ScriptCommandLine[[3]]]], 1];

mA     = Sqrt[mAsq];
JA     = 0;
m2sq   = 1;        (* X2, units m2 = 1                                    *)
J2     = 2;

mgapSq = 166/100;        (* neutral continuum M^2 >= mgapSq, J even             *)
mcSq   = 1;        (* charged continuum M^2 >= mcSq,   all J              *)

boundType = "upper";   (* "upper" or "lower"                              *)

dPhiSupp = Pi/4;     (* phase step of the supplementary masses              *)
bMaxSupp = 100;      (* impact-parameter window b = 2J/M <= bMaxSupp        *)
suppMinJ = 40;       (* below this J the 150 base masses already resolve    *)

neutralSpins = Join[Range[0, 200, 2], {400, 1000, 10000, 50000}];
chargedSpins = Join[Range[0, 200], Flatten[{#, # + 1} & /@ {400, 1000, 10000, 50000}]];



(* ------------------------------------------------------------------------ *)
(* BLOCK 2.  Null indices                                                   *)
(*                                                                          *)
(* row n  <->  (k,q), the coefficient of (s-s0)^(k-q) t^q                   *)
(*   AAAA  (s0 = 0)      n = 0..3 : (1,0) (2,0) (3,0) (3,1)  = test20       *)
(*   BBBB  (s0 = 0)      n = 0..2 : (1,0) (2,0) (3,0)                       *)
(*         [(3,1) vanishes identically for massless externals]              *)
(*   AB    (s0 = -mA^2)  n = 0..5 : (0,0) (1,0) (1,1) (2,0) (2,1) (2,2)     *)
(* ------------------------------------------------------------------------ *)
g0AAWeight[x_] := 2/(x - 2 mAsq);     (* ghatA at (s,t) = (2mA^2, 0) *)
g0BBWeight[x_] := 2/x;                (* ghatB at (s,t) = (0, 0)     *)

(* phi = (2p)^7/Sqrt[x].  Neutral element ij carries Sqrt[phi_i phi_j]:   *)
(* congruence diag(Sqrt[phiAA], Sqrt[phiBB]), PSD cone unchanged.         *)
phiAA[x_] := (x - 4 mAsq)^(7/2)/Sqrt[x];
phiBB[x_] := x^3;
phiAB[x_] := (x - mAsq)^7/x^4;

aaNullIndices = Range[0, 48];
bbNullIndices = Range[0, 50];
abNullIndices = Range[0, 44];

nullCount = Total[
  Length /@ {abNullIndices, aaNullIndices, bbNullIndices}
];

list0 = ConstantArray[0, nullCount];
functionalDimension = 3 + nullCount;

(* supplementary masses: phase (J+7/2) theta = j dPhiSupp, up to the gap or b = bMaxSupp *)
thetaSupp["neutral", M2_] := ArcSin[2 Sqrt[mAsq/M2]];
thetaSupp["charged", M2_] := ArcCos[1 - 2 mAsq (M2 + mAsq)/(M2 - mAsq)^2];
massSupp["neutral", th_]  := 4 mAsq/Sin[th]^2;
massSupp["charged", th_]  := With[{c = 1 - Cos[th]}, mAsq ((c + 1) + Sqrt[4 c + 1])/c];

suppMasses[sec_, J_, gapSq_, prec_] := If[J < suppMinJ, {},
  Module[{nn = J + 7/2, K},
    K = Floor[N[Min[nn thetaSupp[sec, gapSq], Sqrt[mAsq] bMaxSupp]/dPhiSupp, 50]];
    Table[N[massSupp[sec, j dPhiSupp/nn], prec], {j, 1, K}]]];


Get[FileNameJoin[{FileDir, "..", "kernels_AB.m"}]];   (* NABAB, NAABB, nGeg -- generated by ../ABAB_check.m *)






