(* light pole terms *)

(* couplings are gAAA gABB exchanges A *)
nlABAB[n_,x_,J_,mA_] := {-mA^(-2), 0, -mA^(-4), 0, 0, -mA^(-6), 0, 0, 0, -mA^(-8), 0, 0, 0, 0, -mA^(-10), 0, 0, 0, 0, 0, -mA^(-12), 0, 0, 0, 0, 0, 0, -mA^(-14), 0, 0, 0, 0, 0, 0, 0, -mA^(-16), 0, 0, 0, 0, 0, 0, 0, 0, -mA^(-18)}[[n+1]];


(* couplings are gABB gABB exchanges B *)
nlAABB[n_,x_,J_,mA_] := {-mA^(-2), -mA^(-4), 0, -mA^(-6), 0, 0, -mA^(-8), 0, 0, 0, -mA^(-10), 0, 0, 0, 0, -mA^(-12), 0, 0, 0, 0, 0, -mA^(-14), 0, 0, 0, 0, 0, 0, -mA^(-16), 0, 0, 0, 0, 0, 0, 0, -mA^(-18), 0, 0, 0, 0, 0, 0, 0, 0}[[n+1]];




nlBBBB[n_,z_,J_,m_] := {m^(-4), m^(-6), m^(-8), m^(-10), 0, m^(-12), 0, m^(-14), 0, m^(-16), 0, 0, m^(-18), 0, 0, m^(-20), 0, 0, m^(-22), 0, 0, 0, m^(-24), 0, 0, 0, m^(-26), 0, 0, 0, m^(-28), 0, 0, 0, 0, m^(-30), 0, 0, 0, 0, m^(-32), 0, 0, 0, 0, m^(-34), 0, 0, 0, 0, 0}[[n+1]];




nlAAAA[n_,x_,J_,m_] := {m^(-4), m^(-6), m^(-8), 0, m^(-10), 0, m^(-12), 0, 0, m^(-14), 0, 0, m^(-16), 0, 0, 0, m^(-18), 0, 0, 0, m^(-20), 0, 0, 0, 0, m^(-22), 0, 0, 0, 0, m^(-24), 0, 0, 0, 0, 0, m^(-26), 0, 0, 0, 0, 0, m^(-28), 0, 0, 0, 0, 0, 0}[[n+1]];




(* light pole terms *)

(* at state A; the BB entry also carries the B exchange in AB->AB (nlAABB):  *)
(* its weight is gABB^2 = A's BB coupling, so B is not an independent block   *)
nlABMatrix[n_, z_, J_] := {
  {0, -1/2 nlABAB[n, z, J, mA]},
  {-1/2 nlABAB[n, z, J, mA], nlAABB[n, z, J, mA]}
};


nlAAMatrix[n_, z_, J_] := {
  {nlAAAA[n, z, J, mA], 0},
  {0,0}
};


nlBBMatrix[n_, z_, J_] := {
  {0, 0},
  {0, nlBBBB[n, z, J, mA]}
};




(* ------------------------------------------------------------------------ *)
(* BLOCK 12.  Assemble and write                                            *)
(* ------------------------------------------------------------------------ *)

LaunchKernels[];

PMP2SDP[datfile_, prec_: 600] := Module[
  {
    npts = 150, sgn,
    Fn, Fc, FA, pols,
    phiSamples, massSamples, massList, norm, obj
  },

  phiSamples = N[Table[Pi/2 + Pi/2 Cos[(k + 1/2) Pi/npts], {k, 0, npts - 1}], prec];
  massSamples = Sin[#/2]^2 & /@ phiSamples;
  massList["neutral", J_] := Join[mgapSq/(1 - massSamples), suppMasses["neutral", J, mgapSq, prec]];
  massList["charged", J_] := Join[mcSq/(1 - massSamples),  suppMasses["charged", J, mcSq,  prec]];

  Fn[j_, x_, y_] := Module[{w, gB, gA, lam, polys},
    w  = Sqrt[phiAA[x]*phiBB[x]];                     (* off-diagonal weight *)
    gB = {{0, 0}, {0, phiBB[x]*g0BBWeight[x]}};
    gA = {{phiAA[x]*g0AAWeight[x], 0}, {0, 0}};

    lam = {{0, 0}, {0, 0}}; 

    polys = Join[
      {gB, gA, lam},
      w*{{0, #/2}, {#/2, 0}} & /@ NAABB[abNullIndices, x, j, mA],
      phiAA[x]*{{#, 0}, {0, 0}} & /@ NAAAA[aaNullIndices, x, j, mA],
      phiBB[x]*{{0, 0}, {0, #}} & /@ NBBBB[bbNullIndices, x, j, mA]
    ];

    PositiveMatrixWithPrefactor[
        DampedRational[1, {}, 1/E, y],
        Table[
            Table[polys[[k, row, column]], {k, Length[polys]}],
            {row, 2}, {column, 2}
        ]
    ]
  ];

  Fc[j_, x_, y_] := Module[{polys},
    polys = Join[
      {0, 0, 0},
      phiAB[x]*NABAB[abNullIndices, x, j, mA],
      0 & /@ aaNullIndices,
      0 & /@ bbNullIndices
    ];

    PositiveMatrixWithPrefactor[
        DampedRational[1, {}, 1/E, y],
        {{polys}}
    ]
  ];


  (* A (neutral, couplings gAAA, gABB) + B exchange in AB->AB (weight gABB^2) *)
  FA[j_, x_, y_] := Module[{zero2, polys},
    zero2 = ConstantArray[0, {2, 2}];

    polys = Join[
      {zero2, zero2, {{0, 0}, {0, 1}}},
      nlABMatrix[#, mAsq, JA] & /@ abNullIndices,
      nlAAMatrix[#, mAsq, JA] & /@ aaNullIndices,
      nlBBMatrix[#, mAsq, JA] & /@ bbNullIndices
    ];

    PositiveMatrixWithPrefactor[
        DampedRational[1, {}, 1/E, y],
        Table[
            Table[polys[[k, row, column]], {k, Length[polys]}],
            {row, 2}, {column, 2}
        ]
    ]
  ];


  pols = Flatten[{
      Flatten[ N[ ParallelTable[ FA[i, mA, x], {i, JA, JA, 2}], prec] ],
      Flatten[ N[ ParallelTable[ Fn[i, 1, x], {i, J2, J2, 2}], prec] ],
      Flatten[ N[ ParallelTable[ Fn[i, M2, x], {i, neutralSpins}, {M2, massList["neutral", i]},
                  Method -> "FinestGrained"], prec] ],
      Flatten[ N[ ParallelTable[ Fc[i, M2, x], {i, chargedSpins}, {M2, massList["charged", i]},
                  Method -> "FinestGrained"], prec] ]
  }, 1];

  
  sgn  = If[boundType === "upper", 1, -1];
  norm = -sgn N[Join[{0, 0, 1}, list0], prec];
  obj  = -N[Join[{1, rRatio, 0}, list0], prec];

  If[
    Length[norm] =!= functionalDimension ||
    Length[obj]  =!= functionalDimension,
    Print["Objective or normalization dimension mismatch."];
    Abort[]
  ];

  Print["functional dimension = ", functionalDimension,
        "  (3 + ", Length[abNullIndices], " AB + ", Length[aaNullIndices],
        " AAAA + ", Length[bbNullIndices], " BBBB)"];
  Print["number of PMP blocks = ", Length[pols]];

  WritePmpJson[
    datfile,
    SDP[obj, norm, pols],
    prec,
    getAnalyticSampleData
  ]
];

PMP2SDP[FileNameJoin[{FileDir,"n_pmp.json"}], 1000];
